import json


class Invalid(Exception):
    pass


def rows_json(n):
    seed = 11
    parts = []
    for i in range(n):
        seed = seed * 16807 % 2147483647
        amount = str(seed % 100000) + (".0" if i % 5 == 0 else "")
        active = "true" if seed % 7 != 0 else "false"
        parts.append('{"account": "acct-%03d", "amount_cents": %s, "active": %s}' % (seed % 97, amount, active))
    return "[" + ", ".join(parts) + "]"


def aggregate(raw):
    totals = {}
    for row in json.loads(raw):
        if not row["account"].isascii():
            raise Invalid("non-ASCII account")
        amount = row["amount_cents"]
        if isinstance(amount, float):
            if amount != int(amount) or amount < 0 or amount > 1000000:
                raise Invalid("invalid amount")
            amount = int(amount)
        if amount < 0 or amount > 1000000:
            raise Invalid("invalid amount")
        if row["active"]:
            totals[row["account"]] = totals.get(row["account"], 0) + amount
    out = [{"account": k, "total_cents": totals[k]} for k in sorted(totals)]
    return json.dumps(out, separators=(",", ":"))


def main():
    raw = rows_json(2048)
    check = 0
    for _ in range(20):
        try:
            out = aggregate(raw)
        except Invalid:
            out = "invalid"
        h = 0
        for ch in out:
            h = (h * 31 + ord(ch)) % 1000000007
        check = (check + h + len(out)) % 1000000007
    return check

source.js:
function rowsJson(n) {
  let seed = 11;
  const parts = [];
  for (let i = 0; i < n; i++) {
    seed = seed * 16807 % 2147483647;
    const account = String(seed % 97).padStart(3, "0");
    const amount = String(seed % 100000) + (i % 5 === 0 ? ".0" : "");
    const active = seed % 7 !== 0 ? "true" : "false";
    parts.push(`{"account": "acct-${account}", "amount_cents": ${amount}, "active": ${active}}`);
  }
  return "[" + parts.join(", ") + "]";
}

function aggregate(raw) {
  const totals = new Map();
  for (const row of JSON.parse(raw)) {
    if (!/^[\x00-\x7f]*$/.test(row.account)) throw new Error("non-ASCII account");
    const a = row.amount_cents;
    if (a < 0 || a > 1000000 || a !== Math.floor(a)) throw new Error("invalid amount");
    if (row.active) totals.set(row.account, (totals.get(row.account) ?? 0) + a);
  }
  const keys = [...totals.keys()].sort();
  return JSON.stringify(keys.map(k => ({ account: k, total_cents: totals.get(k) })));
}

function main() {
  const raw = rowsJson(2048);
  let check = 0;
  for (let i = 0; i < 20; i++) {
    let out;
    try { out = aggregate(raw); } catch (e) { out = "invalid"; }
    let h = 0;
    for (let j = 0; j < out.length; j++) h = (h * 31 + out.charCodeAt(j)) % 1000000007;
    check = (check + h + out.length) % 1000000007;
  }
  return check;
}

